203	/// Thread-safe Bloom filter for fast negative lookups.
204	///
205	/// A Bloom filter is a probabilistic data structure that can quickly tell you:
206	/// - Definitely NOT in set (no false negatives)
207	/// - POSSIBLY in set (may have false positives)
208	///
209	/// This is useful for avoiding expensive lookups when the key doesn't exist.
210	pub struct BloomFilter {
211	    bits: Box<[AtomicU64]>,
212	    num_bits: usize,
213	    num_hashes: usize,
214	}
215	
216	impl BloomFilter {
217	    /// Create a new Bloom filter with the given expected number of items and false positive rate.
218	    ///
219	    /// # Arguments
220	    /// * `expected_items` - Expected number of items to insert
221	    /// * `false_positive_rate` - Desired false positive rate (e.g., 0.01 for 1%)
222	    #[must_use]
223	    #[allow(
224	        clippy::cast_precision_loss,
225	        clippy::cast_possible_truncation,
226	        clippy::cast_sign_loss
227	    )] // Bloom filter math: values are bounded by reasonable filter sizes
228	    pub fn new(expected_items: usize, false_positive_rate: f64) -> Self {
229	        // Calculate optimal size: m = -n*ln(p) / (ln(2)^2)
230	        let ln2_squared = std::f64::consts::LN_2 * std::f64::consts::LN_2;
231	        let num_bits =
232	            (-(expected_items as f64) * false_positive_rate.ln() / ln2_squared).ceil() as usize;
233	        let num_bits = num_bits.max(64); // Minimum 64 bits
234	
235	        // Calculate optimal number of hash functions: k = (m/n) * ln(2)
236	        let num_hashes =
237	            ((num_bits as f64 / expected_items as f64) * std::f64::consts::LN_2).ceil() as usize;
238	        let num_hashes = num_hashes.clamp(1, 16); // Between 1 and 16 hash functions
239	
240	        // Allocate bit array (using u64 blocks)
241	        let num_blocks = num_bits.div_ceil(64);
242	        let bits: Vec<AtomicU64> = (0..num_blocks).map(|_| AtomicU64::new(0)).collect();
243	
244	        Self {
245	            bits: bits.into_boxed_slice(),
246	            num_bits,
247	            num_hashes,
248	        }
249	    }
250	
251	    /// Create a Bloom filter with default parameters for typical key-value usage.
252	    /// Expects ~10,000 items with 1% false positive rate.
253	    #[must_use]
254	    pub fn with_defaults() -> Self {
255	        Self::new(10_000, 0.01)
256	    }
257	
258	    /// Add a key to the Bloom filter.
259	    pub fn add<K: Hash>(&self, key: &K) {
260	        for i in 0..self.num_hashes {
261	            let bit_index = self.hash_index(key, i);
262	            let block_index = bit_index / 64;
263	            let bit_offset = bit_index % 64;
264	            self.bits[block_index].fetch_or(1 << bit_offset, Ordering::Relaxed);
265	        }
266	    }
267	
268	    /// Check if a key might be in the set.
269	    /// Returns false if the key is definitely NOT in the set.
270	    /// Returns true if the key MIGHT be in the set (could be false positive).
271	    #[inline]
272	    pub fn might_contain<K: Hash>(&self, key: &K) -> bool {
273	        for i in 0..self.num_hashes {
274	            let bit_index = self.hash_index(key, i);
275	            let block_index = bit_index / 64;
276	            let bit_offset = bit_index % 64;
277	            if (self.bits[block_index].load(Ordering::Relaxed) & (1 << bit_offset)) == 0 {
278	                return false;
279	            }
280	        }
281	        true
282	    }
283	
284	    /// Clear all bits in the filter.
285	    pub fn clear(&self) {
286	        for block in &*self.bits {
287	            block.store(0, Ordering::Relaxed);
288	        }
289	    }
290	
291	    /// Compute hash index for a key with a given seed.
292	    #[inline]
293	    #[allow(clippy::cast_possible_truncation)] // Hash modulo num_bits fits in usize
294	    fn hash_index<K: Hash>(&self, key: &K, seed: usize) -> usize {
295	        let mut hasher = std::hash::DefaultHasher::new();
296	        seed.hash(&mut hasher);
297	        key.hash(&mut hasher);
298	        (hasher.finish() as usize) % self.num_bits
299	    }
300	
301	    /// Returns the number of bits in the filter.
302	    #[must_use]
303	    pub const fn num_bits(&self) -> usize {
304	        self.num_bits
305	    }
306	
307	    /// Returns the number of hash functions used.
308	    #[must_use]
309	    pub const fn num_hashes(&self) -> usize {
310	        self.num_hashes
311	    }
312	}
313	
314	impl std::fmt::Debug for BloomFilter {
315	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
316	        f.debug_struct("BloomFilter")
317	            .field("num_bits", &self.num_bits)
318	            .field("num_hashes", &self.num_hashes)
319	            .finish_non_exhaustive()
320	    }
321	}
322	
323	/// Represents different types of values a tensor can hold
324	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
325	pub enum TensorValue {
326	    /// Scalar values (properties): integers, floats, strings, booleans
327	    Scalar(ScalarValue),
328	    /// Vector values (embeddings): f32 arrays for similarity search
329	    Vector(Vec<f32>),
330	    /// Sparse vector values: only non-zero positions stored
331	    ///
332	    /// Philosophy: Zero represents absence of information, not a stored value.
333	    /// The dimension defines the boundary/shell of meaningful space.
334	    Sparse(SparseVector),
335	    /// Pointer to another tensor (relationships)
336	    Pointer(String),
337	    /// List of pointers (multiple relationships)
338	    Pointers(Vec<String>),
339	}
340	
341	/// Default sparsity threshold for auto-sparsification (70%)
342	pub const DEFAULT_SPARSITY_THRESHOLD: f32 = 0.7;
343	
344	/// Default value threshold for pruning small values
345	pub const DEFAULT_VALUE_THRESHOLD: f32 = 0.01;
346	
347	impl TensorValue {
348	    /// Create an embedding value, automatically choosing sparse or dense representation.
349	    ///
350	    /// If the vector has sparsity above `sparsity_threshold` after pruning values
351	    /// below `value_threshold`, stores as `Sparse`. Otherwise stores as `Vector`.
352	    ///
353	    /// # Example
354	    ///
355	    /// ```
356	    /// use tensor_store::TensorValue;
357	    ///
358	    /// // Dense embedding - stored as Vector
359	    /// let dense = vec![0.5, 0.3, 0.8, 0.2];
360	    /// let val = TensorValue::from_embedding(dense.clone(), 0.01, 0.7);
361	    /// assert!(matches!(val, TensorValue::Vector(_)));
362	    ///
363	    /// // Sparse embedding - stored as Sparse
364	    /// let sparse = vec![0.0, 0.0, 0.5, 0.0, 0.0, 0.0, 0.3, 0.0, 0.0, 0.0];
365	    /// let val = TensorValue::from_embedding(sparse, 0.01, 0.7);
366	    /// assert!(matches!(val, TensorValue::Sparse(_)));
367	    /// ```
368	    #[must_use]
369	    pub fn from_embedding(dense: Vec<f32>, value_threshold: f32, sparsity_threshold: f32) -> Self {
370	        let sparse = SparseVector::from_dense_with_threshold(&dense, value_threshold);
371	
372	        if sparse.sparsity() >= sparsity_threshold {
373	            Self::Sparse(sparse)
374	        } else {
375	            Self::Vector(dense)
376	        }
377	    }
378	
379	    /// Create an embedding with default thresholds (0.01 value, 0.7 sparsity).
380	    #[must_use]
381	    pub fn from_embedding_auto(dense: Vec<f32>) -> Self {
382	        Self::from_embedding(dense, DEFAULT_VALUE_THRESHOLD, DEFAULT_SPARSITY_THRESHOLD)
383	    }
384	
385	    /// Convert to dense vector representation (for compatibility with dense operations).
386	    ///
387	    /// Returns `Some(Vec<f32>)` for Vector or Sparse variants, `None` otherwise.
388	    #[must_use]
389	    pub fn to_dense(&self) -> Option<Vec<f32>> {
390	        match self {
391	            Self::Vector(v) => Some(v.clone()),
392	            Self::Sparse(s) => Some(s.to_dense()),
393	            _ => None,
394	        }
