39	    pub engine: Arc<VectorEngine>,
40	    /// Authentication configuration.
41	    pub auth_config: Option<AuthConfig>,
42	    /// Rate limiter.
43	    pub rate_limiter: Option<Arc<RateLimiter>>,
44	    /// Audit logger.
