54	impl VectorApiContext {
55	    /// Create a new context with a vector engine.
56	    #[must_use]
57	    pub const fn new(engine: Arc<VectorEngine>) -> Self {
58	        Self {
59	            engine,
60	            auth_config: None,
61	            rate_limiter: None,
62	            audit_logger: None,
63	            metrics: None,
64	            spatial: None,
65	            spatial_3d: None,
66	        }
67	    }
