139	impl RestConfig {
140	    /// Create a new REST configuration.
141	    #[must_use]
142	    pub fn new() -> Self {
143	        Self::default()
144	    }
145	
146	    /// Set maximum body size.
147	    #[must_use]
148	    pub const fn with_max_body_size(mut self, size: usize) -> Self {
149	        self.max_body_size = size;
150	        self
151	    }
152	
153	    /// Enable CORS.
154	    #[must_use]
155	    pub const fn with_cors(mut self, enabled: bool) -> Self {
156	        self.cors_enabled = enabled;
157	        self
158	    }
159	
160	    /// Set CORS allowed origins.
161	    #[must_use]
162	    pub fn with_cors_origins(mut self, origins: Vec<String>) -> Self {
163	        self.cors_origins = origins;
164	        self
165	    }
166	}
