168	/// Create the REST API router.
169	pub fn router(ctx: Arc<VectorApiContext>) -> Router {
170	    router_with_config(ctx, &RestConfig::default())
171	}
172	
173	/// Create the REST API router with configuration.
174	pub fn router_with_config(ctx: Arc<VectorApiContext>, config: &RestConfig) -> Router {
175	    let mut router = Router::new()
176	        // Points endpoints
177	        .route(
178	            "/collections/{name}/points",
179	            put(points::upsert).post(points::upsert),
180	        )
181	        .route("/collections/{name}/points/get", post(points::get))
182	        .route("/collections/{name}/points/delete", post(points::delete))
183	        .route("/collections/{name}/points/query", post(points::query))
184	        .route("/collections/{name}/points/scroll", post(points::scroll))
185	        // Collections endpoints
186	        .route("/collections/{name}", put(collections::create))
187	        .route("/collections/{name}", get(collections::get))
188	        .route("/collections/{name}", delete(collections::delete))
189	        .route("/collections", get(collections::list))
190	        // Spatial endpoints (2D)
191	        .route(
192	            "/collections/{name}/spatial/insert",
193	            post(spatial::insert),
194	        )
195	        .route("/collections/{name}/spatial/query", post(spatial::query))
196	        .route(
197	            "/collections/{name}/spatial/delete",
198	            post(spatial::delete),
199	        )
200	        .route("/collections/{name}/spatial/count", get(spatial::count))
201	        // Spatial 3D endpoints
202	        .route(
203	            "/collections/{name}/spatial3d/insert",
204	            post(spatial3d::insert_3d),
205	        )
206	        .route(
207	            "/collections/{name}/spatial3d/query",
208	            post(spatial3d::query_3d),
209	        )
210	        .route(
211	            "/collections/{name}/spatial3d/nearest",
212	            post(spatial3d::nearest_3d),
213	        )
214	        .route(
215	            "/collections/{name}/spatial3d/region",
216	            post(spatial3d::region_3d),
217	        )
218	        .route(
219	            "/collections/{name}/spatial3d/delete",
220	            post(spatial3d::delete_3d),
221	        )
222	        .route(
223	            "/collections/{name}/spatial3d/count",
224	            get(spatial3d::count_3d),
225	        )
226	        // Middleware
227	        .layer(TraceLayer::new_for_http())
228	        .layer(RequestBodyLimitLayer::new(config.max_body_size))
229	        .with_state(ctx);
230	
231	    // Apply CORS if configured
232	    if config.cors_enabled {
233	        let origins: Vec<HeaderValue> = config
234	            .cors_origins
235	            .iter()
236	            .filter_map(|o| o.parse().ok())
237	            .collect();
238	        let cors = CorsLayer::new()
239	            .allow_origin(origins)
240	            .allow_methods([Method::GET, Method::POST, Method::OPTIONS])
241	            .allow_headers([header::CONTENT_TYPE, HeaderName::from_static("x-api-key")]);
242	        router = router.layer(cors);
243	    }
244	
245	    router
246	}
