23	/// Converts a `TensorValue` back to a JSON value for payload retrieval.
24	fn tensor_value_to_json(value: &TensorValue) -> serde_json::Value {
25	    match value {
26	        TensorValue::Scalar(s) => match s {
27	            ScalarValue::Null => serde_json::Value::Null,
28	            ScalarValue::Bool(b) => serde_json::Value::Bool(*b),
29	            ScalarValue::Int(i) => serde_json::json!(*i),
30	            ScalarValue::Float(f) => serde_json::Number::from_f64(*f)
31	                .map_or(serde_json::Value::Null, serde_json::Value::Number),
32	            ScalarValue::String(s) => serde_json::Value::String(s.clone()),
33	            ScalarValue::Bytes(b) => serde_json::Value::String(
34	                String::from_utf8(b.clone()).unwrap_or_else(|e| format!("{:02x?}", e.into_bytes())),
35	            ),
36	        },
37	        TensorValue::Vector(v) => serde_json::json!(v),
38	        TensorValue::Sparse(_) => serde_json::Value::String("(sparse vector)".to_string()),
39	        TensorValue::Pointer(p) => serde_json::Value::String(p.clone()),
40	        TensorValue::Pointers(ps) => serde_json::json!(ps),
41	    }
42	}
