44	/// Retrieves stored metadata for a point as a JSON payload map.
45	fn retrieve_payload_json(
46	    engine: &vector_engine::VectorEngine,
47	    collection: &str,
48	    key: &str,
49	) -> Option<std::collections::HashMap<String, serde_json::Value>> {
50	    let metadata = engine.get_collection_metadata(collection, key).ok()?;
51	    if metadata.is_empty() {
52	        return None;
53	    }
54	    Some(
55	        metadata
56	            .into_iter()
57	            .map(|(k, v)| (k, tensor_value_to_json(&v)))
58	            .collect(),
59	    )
60	}
