62	fn json_to_tensor_value(value: &serde_json::Value) -> TensorValue {
63	    match value {
64	        serde_json::Value::Null => TensorValue::Scalar(ScalarValue::Null),
65	        serde_json::Value::Bool(b) => TensorValue::Scalar(ScalarValue::Bool(*b)),
66	        serde_json::Value::Number(n) => n.as_i64().map_or_else(
67	            || {
68	                n.as_f64()
69	                    .map_or(TensorValue::Scalar(ScalarValue::Null), |f| {
70	                        TensorValue::Scalar(ScalarValue::Float(f))
71	                    })
72	            },
73	            |i| TensorValue::Scalar(ScalarValue::Int(i)),
74	        ),
75	        serde_json::Value::String(s) => TensorValue::Scalar(ScalarValue::String(s.clone())),
76	        serde_json::Value::Array(_) | serde_json::Value::Object(_) => {
77	            TensorValue::Scalar(ScalarValue::String(value.to_string()))
78	        },
79	    }
80	}
