96	pub async fn upsert(
97	    State(ctx): State<Arc<VectorApiContext>>,
98	    Path(collection): Path<String>,
99	    headers: HeaderMap,
100	    Json(request): Json<UpsertRequest>,
101	) -> ApiResult<UpsertResponse> {
102	    let start = Instant::now();
103	
104	    let identity = validate_auth(&headers, ctx.auth_config.as_ref())?;
105	    check_rate_limit(
106	        identity.as_deref(),
107	        ctx.rate_limiter.as_ref(),
108	        Operation::VectorOp,
109	    )?;
110	
111	    let mut count = 0usize;
112	
113	    for point in request.points {
114	        let result = if let Some(ref metadata) = point.payload {
115	            ctx.engine.store_in_collection_with_metadata(
116	                &collection,
117	                &point.id,
118	                point.vector,
119	                convert_metadata(metadata),
120	            )
121	        } else {
122	            ctx.engine
123	                .store_in_collection(&collection, &point.id, point.vector)
124	        };
125	
126	        if let Err(e) = result {
127	            if let Some(ref m) = ctx.metrics {
128	                let latency_ms = start.elapsed().as_secs_f64() * 1000.0;
129	                m.record_request("vector", "upsert", false, latency_ms);
130	            }
131	            return Err(ApiError::internal(e.to_string()));
132	        }
133	        count += 1;
134	    }
135	
136	    // Record metrics
137	    if let Some(ref m) = ctx.metrics {
138	        let latency_ms = start.elapsed().as_secs_f64() * 1000.0;
139	        m.record_vector_latency("upsert", latency_ms);
140	        m.record_request("vector", "upsert", true, latency_ms);
141	    }
142	
143	    // Audit log
144	    if let Some(ref logger) = ctx.audit_logger {
145	        logger.record(
146	            AuditEvent::VectorUpsert {
147	                identity,
148	                collection,
149	                count,
150	            },
151	            None,
152	        );
153	    }
154	
155	    Ok(Json(UpsertResponse {
156	        status: "ok".to_string(),
157	        upserted: count,
158	    }))
159	}
