25	fn parse_distance_metric(distance: &str) -> Result<DistanceMetric, ApiError> {
26	    match distance.to_lowercase().as_str() {
27	        "cosine" | "" => Ok(DistanceMetric::Cosine),
28	        "euclidean" | "l2" => Ok(DistanceMetric::Euclidean),
29	        "dot" | "dot_product" | "inner_product" => Ok(DistanceMetric::DotProduct),
30	        "poincare" | "hyperbolic" => Ok(DistanceMetric::Poincare),
31	        _ => Err(ApiError::bad_request(format!(
32	            "unknown distance metric: {distance}. Expected: cosine, euclidean, dot, or poincare"
33	        ))),
34	    }
35	}
36	
37	const fn metric_to_string(metric: DistanceMetric) -> &'static str {
38	    match metric {
39	        DistanceMetric::Cosine => "cosine",
40	        DistanceMetric::Euclidean => "euclidean",
41	        DistanceMetric::DotProduct => "dot",
42	        DistanceMetric::Poincare => "poincare",
43	    }
44	}
